(r, big) => {
    if (!big && r.bool(0.5)) return [r.str(r.int(1, 12), "abAB01 ,.!_")];
    // a palindrome over letters and digits, then random case and punctuation mixed in
    const n = big ? 160000 : r.int(1, 10);
    const half = r.str(Math.floor(n / 2), "ab01");
    const mid = n % 2 ? r.str(1, "ab01") : "";
    const clean = half + mid + half.split("").reverse().join("");
    let out = "";
    for (const c of clean) {
      out += r.bool(0.5) ? c.toUpperCase() : c;
      if (r.bool(0.2)) out += r.pick([" ", ",", ".", "!", "_"]);
    }
    return [out];
  }

