function isMirrored(s: string): boolean {
  const counts = (c: string) => /[a-z0-9]/i.test(c);
  let lo = 0, hi = s.length - 1;
  while (lo < hi) {
    if (!counts(s[lo])) { lo++; continue; }
    if (!counts(s[hi])) { hi--; continue; }
    if (s[lo].toLowerCase() !== s[hi].toLowerCase()) return false;
    lo++;
    hi--;
  }
  return true;
}

